# pc-v59: fixes from the three screen walkthroughs. One docked bar above the tabs holds the session clock and the Rest
# timer (nothing floats over the workout), ‹ Back stays on screen, Continue returns to where you were, Done after a save
# lands outside the session, the Today card reads the real state of the day (draft, paused, skipped, extra) and previews
# the session, an empty "something else" cannot be saved, Week lists the seven days, and wording / tap sizes are fixed.
from playwright.sync_api import sync_playwright
from lib import *
MON="2026-11-09";WED="2026-11-11";THU="2026-11-12"
home=lambda p:p.locator("#home").inner_text().split("\n")
rect=lambda p,s:p.evaluate("s=>{var r=document.querySelector(s).getBoundingClientRect();return [r.left,r.top,r.right,r.bottom]}",s)
with sync_playwright() as pw:
    b=launch(pw)
    c,p=tabs_app(b,THU)
    ok("Today previews the session: one row per block",p.locator("#home .hprev div").count()==6 and p.locator("#home .hprev").inner_text().startswith("WARM-UP"),p.locator("#home .hprev").inner_text())
    ok("the week line counts the whole week",home(p)[-1]=="This week · 0 of 5 sessions ›",home(p)[-1])
    ok("tab icons are drawn, not glyphs",p.locator("#tabbar button svg.ti").count()==3 and p.locator("#tabbar button").all_inner_texts()==["Today","Week","Progress"])
    p.click('#home .hprev');p.wait_for_timeout(300)
    ok("tapping the preview opens the session without starting the clock",p.locator("#panel.open").count()==1 and not ls(p,"wo_"+THU) or not (ls(p,"wo_"+THU) or {}).get("start"))
    p.click("#close");p.wait_for_timeout(200);ok("a look and Back leaves Today as not started",p.locator('#home [data-hm="start"]').count()==1)
    p.click('#home [data-hm="start"]');p.wait_for_timeout(400)
    d=rect(p,"#dock");tb=rect(p,"#tabbar");sc=rect(p,"#sclk");rb=rect(p,"#rbtn")
    ok("the dock sits on the tab bar and holds the clock and the Rest timer",abs(d[3]-tb[1])<1.5 and sc[1]>=d[1] and sc[3]<=d[3] and rb[1]>=d[1] and rb[3]<=d[3] and sc[2]<rb[0],(d,tb,sc,rb))
    ok("nothing floats over the first guided button",p.evaluate("()=>{var b=document.querySelector('#sess [data-t]');b.scrollIntoView({block:'center'});var r=b.getBoundingClientRect(),e=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2),d=document.getElementById('dock').getBoundingClientRect();return r.bottom<=d.top&&b.contains(e)}"))
    xs=p.evaluate("()=>{var o=[];[].forEach.call(document.querySelectorAll('.srow'),function(r){if(o.indexOf(r.dataset.x)<0)o.push(r.dataset.x)});return o.slice(0,2)}")
    p.evaluate("()=>document.querySelector('.srow').scrollIntoView({block:'center'})");p.wait_for_timeout(100);y0=p.evaluate("scrollY")
    ok("‹ Back stays on screen after scrolling",y0>300 and p.locator("#close").is_visible() and rect(p,"#close")[1]<60 and rect(p,"#close")[1]>=0,(y0,rect(p,"#close")))
    tick(p,xs[0],0);tick(p,xs[1],0);p.wait_for_timeout(200)
    ok("the rest bar takes the dock's place; the page is not covered twice",p.locator("#rbar.show").count()==1 and abs(rect(p,"#rbar")[3]-tb[1])<1.5 and p.locator("#sclk").is_hidden(),rect(p,"#rbar"))
    y1=p.evaluate("scrollY");p.click('#tabbar [data-tab="prog"]');p.wait_for_timeout(200)
    ok("the rest bar does not follow you to another tab",p.locator("#rbar").is_hidden())
    p.click('#tabbar [data-tab="today"]');p.wait_for_timeout(200);p.click('#home [data-hm="open"]');p.wait_for_timeout(300)
    ok("Continue returns to where you were",abs(p.evaluate("scrollY")-y1)<5,(y1,p.evaluate("scrollY")))
    fin(p);p.click("#o_done");p.wait_for_timeout(300)
    ok("Done after Finish closes the session, clears the rest and lands on Today",p.locator("#panel.open").count()==0 and p.locator("#home .hline").inner_text().startswith("✓ Logged") and p.locator("#rbar").is_hidden() and ls(p,"wo_rest") is None and p.evaluate("scrollY")==0)
    p.click('#tabbar [data-tab="prog"]');p.wait_for_timeout(200)
    ok("Progress: sessions out of the whole week, minutes labelled running",p.locator(".wkbig div").first.inner_text().replace("\n","")=="1/5sessions" and p.locator(".wkbig div").nth(3).inner_text().split("\n")[-1]=="running",p.locator(".wkbig").inner_text())
    c.close()
    # ---- something else: abandon, empty save, real save ----
    c,p=tabs_app(b,THU);p.click('#home [data-hm="else"]');p.wait_for_timeout(300)
    ok("the short form fits one screen: Save is above the tab bar",rect(p,"#fin2")[3]<=rect(p,"#tabbar")[1],(rect(p,"#fin2"),rect(p,"#tabbar")))
    p.click("#fin2");p.wait_for_timeout(200)
    ok("an empty something else is not saved",p.locator("#ov.show").count()==0 and not ls(p,"wo_log") and "time or a distance" in p.locator("#toast").inner_text())
    p.click("#close");p.wait_for_timeout(200)
    ok("leaving it empty puts today back on the plan",p.locator('#home [data-hm="start"]').count()==1 and not (ls(p,"wo_run_"+THU) or {}).get("sub") and (ls(p,"wo_"+THU) or {}).get("oc","")=="")
    p.click('#home [data-hm="else"]');p.wait_for_timeout(300);p.fill("#r_d","5");p.locator("#r_d").blur();p.click("#close");p.wait_for_timeout(200)
    ok("a part filled one is kept and Today says so",home(p)[:3]==["Marked as something else · not saved yet","Finish logging","Back to the plan"],home(p))
    p.click('#home [data-hm="plan"]');p.wait_for_timeout(150);ok("Back to the plan in one tap",p.locator('#home [data-hm="start"]').count()==1 and not ls(p,"wo_run_"+THU).get("sub"))
    p.click('#home [data-hm="else"]');p.wait_for_timeout(300);p.fill("#r_t","2940");p.locator("#r_t").blur();p.wait_for_timeout(100);fin(p);p.click("#o_done");p.wait_for_timeout(300)
    ok("saved: one record, back on Today reading what was done",len(ls(p,"wo_log"))==1 and ls(p,"wo_log")[0]["time"]=="29:40" and p.locator("#home .hline").inner_text().startswith("✓ Logged · 30 min") and p.locator("#panel.open").count()==0,p.locator("#home").inner_text())
    c.close()
    # ---- Today reads the real state ----
    c,p=tabs_app(b,THU,{"wo_log":[{"date":THU,"name":"Lower · Carry Medley","type":"main","min":0,"oc":"skipped","sid":"x"}]})
    ok("a skipped day is not a green Logged",p.locator("#home .hline").inner_text()=="Skipped today" and p.locator("#home .hline.good").count()==0)
    c.close();c,p=tabs_app(b,THU);p.click('#home [data-hm="start"]');p.wait_for_timeout(200);p.clock.run_for(65000);p.wait_for_timeout(150);p.click('#sclk [data-sc="stop"]');p.wait_for_timeout(100);p.click("#close");p.wait_for_timeout(200)
    ok("a stopped clock reads as paused",p.locator("#home .hline").inner_text().startswith("Paused at 1:05") and p.locator("#home .btn").inner_text()=="Continue",home(p))
    p.click('#home [data-hm="resume"]');p.wait_for_timeout(300)
    ok("Continue resumes the clock",not ls(p,"wo_"+THU).get("end") and p.locator('#sclk [data-sc="lap"]').count()==1 and p.locator("#sclk b").inner_text()=="1:05",p.locator("#sclk").inner_text())
    c.close();c,p=tabs_app(b,THU,{"wo_log":[{"date":THU,"name":"Extra run","type":"extra","extra":1,"act":"run","min":30,"km":"5","time":"29:40"}]})
    ok("an extra logged today shows on the card with the replace offer","Extra run logged ✓" in home(p)[0] and p.locator('#home [data-hm="conv"]').inner_text()=="It replaced this session",home(p))
    p.click('#home [data-hm="conv"]');p.wait_for_timeout(300);ok("which opens the day at the offer",p.locator("#xconv").is_visible())
    # ---- run day, yesterday, week ----
    c.close();c,p=tabs_app(b,WED);ok("a run day offers Log my run",p.locator('#home [data-hm="run"]').inner_text()=="Log my run")
    p.click('#home [data-hm="run"]');p.wait_for_timeout(400)
    ok("it opens at the Actual card without starting the clock",p.evaluate("()=>{var h=[].filter.call(document.querySelectorAll('#sess h2'),function(x){return x.textContent=='Actual'})[0].getBoundingClientRect();return h.top>0&&h.top<200}") and not (ls(p,"wo_"+WED) or {}).get("start"))
    c.close();c,p=tabs_app(b,THU);p.click('#ynag [data-ng="skip"]');p.wait_for_selector("#ov.show");p.clock.run_for(800)
    ok("yesterday skipped: the card says so with a readable date",p.locator("#ov .kicker").inner_text().lower()=="logged as skipped" and p.locator("#o_n").inner_text().endswith("Wed 11 Nov"),p.locator("#ov").inner_text())
    p.click("#o_done");p.wait_for_timeout(300);ok("and Done returns to Today",p.locator("#home").is_visible() and p.locator("#panel.open").count()==0)
    p.click('#tabbar [data-tab="week"]');p.wait_for_timeout(300)
    ok("Week lists the seven days with their state",p.locator("#wlist .wrow").count()==7 and p.locator("#wlist .wrow.today .ws").inner_text()=="Today" and p.locator(f'#wlist [data-d="{WED}"] .ws').inner_text()=="Skipped" and p.locator(f'#wlist [data-d="{MON}"] .ws').inner_text()=="Not logged" and p.locator("#hint").is_hidden(),p.locator("#wlist").inner_text())
    p.click(f'#wlist [data-d="{MON}"]');p.wait_for_timeout(300)
    bg=lambda s:p.evaluate("s=>getComputedStyle(document.querySelector(s)).backgroundColor",s)
    ok("a row opens the day; today is outlined, the open day is filled",p.evaluate("()=>__app.sel")==MON and p.locator("#wlist").is_hidden() and bg(".day.today")!=bg(".day.sel"),(bg(".day.today"),bg(".day.sel")))
    p.click("#close");p.wait_for_timeout(200);p.click('#wlist [data-d="2026-11-14"]');p.wait_for_timeout(300);ok("a future day has no Finish to tap",p.locator("#fin").is_hidden())
    # ---- settings, import, unplanned ----
    p.click('#tabbar [data-tab="today"]');p.wait_for_timeout(200);p.click("#cog");p.wait_for_timeout(200)
    ok("Settings: big ticks in rows of 48 px",p.evaluate("()=>[].every.call(document.querySelectorAll('#sets .setr'),function(l){return l.getBoundingClientRect().height>=48&&l.querySelector('input').getBoundingClientRect().width>=24})"))
    c.close();c,p=tabs_app(b,THU,{"wo_flash":{"week":MON,"msg":"Week saved"}})
    ok("after an import the app lands on Week with the toast",p.evaluate("()=>document.body.classList.contains('t-week')") and p.locator("#wlist").is_visible() and "Week saved" in p.locator("#toast").inner_text())
    c.close();c,p=tabs_app(b,"2026-11-16");ok("an unplanned week says nothing planned",home(p)[-1]=="This week · nothing planned ›",home(p))
    p.click('#home [data-hm="open"]');p.wait_for_timeout(300);t=p.locator("#sess").inner_text()
    ok("and points to Settings for Import week","Settings on the Today screen → Import week" in t and "History →" not in t and "backup from another day" not in t,t[:300])
    c.close();c,p=tabs_app(b,THU,scheme="dark");p.click('#home [data-hm="start"]');p.wait_for_timeout(300)
    ok("dark: the dock is a dark surface",p.evaluate("()=>{var m=getComputedStyle(document.getElementById('dock')).backgroundColor.match(/\\d+/g);return +m[0]+ +m[1]+ +m[2]<200}"))
    c.close();c,p=tabs_app(b,THU,w=375,h=667);p.click('#home [data-hm="start"]');p.wait_for_timeout(300)
    p.click("[data-tqx]");p.wait_for_timeout(150)
    ok("small iPhone: the three top chips stay inside their card",p.evaluate("()=>{var c=document.getElementById('topq').getBoundingClientRect();return [].every.call(document.querySelectorAll('#toc .rc'),function(b){return b.getBoundingClientRect().right<=c.right-8})}"))
    ok("no page errors",not errs,errs);c.close();b.close()
exit(done())
